function productionCompare(candidateId,wholeOverride=false){const p=P(),s=S(),panel=s.panels[compositionPanel],whole=wholeOverride||!!s.upload,target=whole?s:panel,candidate=target.imageCandidates.find(x=>x.id===candidateId);if(!candidate)return;const dialog=productionDialog((whole?'Full page':'Episode '+(compositionPanel+1)+'Panel')+' · Candidate comparison'),body=dialog.querySelector('.pr-dialog-body'),grid=document.createElement('div');grid.className='pr-compare';const old=document.createElement('figure'),next=document.createElement('figure'),oldImage=document.createElement('img'),newImage=document.createElement('img');oldImage.src=whole?(s.upload||$('cpCanvas').toDataURL()):panel.upload||productionCurrentImage();newImage.src=candidate.image;old.innerHTML='<figcaption>Current art · original kept</figcaption>';next.innerHTML='<figcaption>Uploaded candidate · not adopted yet</figcaption>';old.append(oldImage);next.append(newImage);grid.append(old,next);body.append(grid);const adopt=document.createElement('button');adopt.textContent=target.adoptedImageId===candidate.id?'This version is adopted':'Adopt this candidate';adopt.disabled=target.adoptedImageId===candidate.id;adopt.onclick=()=>{if(!confirm('Adopt this candidate as replacement'+(whole?'Full-page image':'Episode '+(compositionPanel+1)+'Panel image')+'? The old image and crop are archived; other panels, text layers and visual references stay.'))return;try{M.productionAdopt(p,p.scene,whole?null:panel.id,candidate.id);save();dialog.close();compositionRender();}catch(error){$('stageMessage').textContent=error.message;}};body.append(adopt);}
