async function productionZip(files){const parts=[],directory=[],encoder=new TextEncoder();let offset=0;const header=(size)=>{const bytes=new Uint8Array(size);return {bytes,view:new DataView(bytes.buffer)};};for(const file of files){const name=encoder.encode(file.name),data=new Uint8Array(await file.blob.arrayBuffer());let crc=0xffffffff;for(const byte of data){crc^=byte;for(let bit=0;bit<8;bit++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}crc=(crc^0xffffffff)>>>0;const local=header(30);local.view.setUint32(0,0x04034b50,true);local.view.setUint16(4,20,true);local.view.setUint16(6,0x800,true);local.view.setUint32(14,crc,true);local.view.setUint32(18,data.length,true);local.view.setUint32(22,data.length,true);local.view.setUint16(26,name.length,true);parts.push(local.bytes,name,data);const central=header(46);central.view.setUint32(0,0x02014b50,true);central.view.setUint16(4,20,true);central.view.setUint16(6,20,true);central.view.setUint16(8,0x800,true);central.view.setUint32(16,crc,true);central.view.setUint32(20,data.length,true);central.view.setUint32(24,data.length,true);central.view.setUint16(28,name.length,true);central.view.setUint32(42,offset,true);directory.push(central.bytes,name);offset+=30+name.length+data.length;}const size=directory.reduce((sum,x)=>sum+x.length,0),end=header(22);end.view.setUint32(0,0x06054b50,true);end.view.setUint16(8,files.length,true);end.view.setUint16(10,files.length,true);end.view.setUint32(12,size,true);end.view.setUint32(16,offset,true);return new Blob([...parts,...directory,end.bytes],{type:'application/zip'});}
async function productionExport(episode=false){const p=clone(P()),pages=episode?p.scenes.map((s,i)=>({s,i})).filter(x=>x.s.episodeId===p.activeEpisodeId):[{s:p.scenes[p.scene],i:p.scene}];if(pages.some(x=>!M.productionComplete(x.s))&&!confirm('Selected'+pages.length+'Some pages are missing art, so the PNG will include explicit not-yet-generated placeholders. Export anyway?'))return;const files=[];$('cpMessage').textContent='Rendering the export on the shared canvas…';try{for(const {s,i}of pages){const canvas=document.createElement('canvas');await R.draw(canvas,p,i);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG encoding failed');files.push({name:String(files.length+1).padStart(2,'0')+'-'+s.name.replace(/[\\/:*?"<>|]/g,'_')+'.png',blob});}const label=(p.title||'comic').replace(/[\\/:*?"<>|]/g,'_');productionDownload(episode?await productionZip(files):files[0].blob,label+(episode?'-full-episode.zip':'-No. '+(p.scene+1)+'.png'));}catch(error){$('cpMessage').textContent='Export failed: '+error.message;}}
